</head>
<body>
    <style>

        .lonely-status-container {
            --klein-deep: #001133;
            --klein-core: #002FA7;
            --klein-mid: #1a4fd9;
            --klein-light: #3d6fcc;
            --klein-glow: rgba(0, 47, 167, 0.5);
            --void-black: #050a14;
            --mist-blue: #1a2a4a;
            --text-soul: #d8e4f8;
            --text-ghost: #8a9fc4;
            --text-ash: #4a5a7a;
            --gold-whisper: #b8a068;
            --rose-dying: #9a5a68;
            --frost: rgba(180, 200, 230, 0.08);
            font-family: "KingHwaOldSong", "Noto Serif SC", serif;
            width: 100%;
            max-width: 680px;
            margin: 16px auto;
            border-radius: 2px;
            overflow: visible;
            position: relative;
            color: var(--text-soul);
            line-height: 1.7;
        }

        .lonely-status-container .bg-layer {
            position: absolute;
            inset: 0;
            border-radius: 2px;
            z-index: 0;
        }

        .lonely-status-container .bg-abyss {
            background:
                radial-gradient(ellipse 120% 80% at 50% 120%, var(--klein-core) 0%, transparent 50%),
                radial-gradient(ellipse 80% 60% at 80% 20%, rgba(0, 40, 100, 0.4) 0%, transparent 40%),
                linear-gradient(180deg, var(--void-black) 0%, var(--klein-deep) 40%, var(--void-black) 100%);
            animation: abyssBreath 8s ease-in-out infinite;
        }
        @keyframes abyssBreath {
            0%, 100% { opacity: 1; }
            50% { opacity: 0.85; }
        }

        .lonely-status-container .bg-mist {
            background:
                radial-gradient(ellipse 100% 50% at 20% 80%, rgba(26, 79, 217, 0.15) 0%, transparent 50%),
                radial-gradient(ellipse 80% 40% at 80% 20%, rgba(26, 79, 217, 0.1) 0%, transparent 40%);
            animation: mistFlow 15s ease-in-out infinite;
        }
        @keyframes mistFlow {
            0%, 100% { transform: translateX(0) translateY(0); opacity: 0.6; }
            33% { transform: translateX(10px) translateY(-5px); opacity: 0.8; }
            66% { transform: translateX(-8px) translateY(3px); opacity: 0.5; }
        }

        .lonely-status-container .bg-noise {
            background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
            opacity: 0.03;
            mix-blend-mode: overlay;
        }

        .lonely-status-container .rain-layer {
            position: absolute;
            inset: 0;
            overflow: hidden;
            border-radius: 2px;
            z-index: 1;
            pointer-events: none;
        }
        .lonely-status-container .raindrop {
            position: absolute;
            width: 1px;
            background: linear-gradient(180deg, transparent, rgba(140, 180, 220, 0.4), transparent);
            animation: rainFall linear infinite;
            opacity: 0;
        }
        .lonely-status-container .raindrop:nth-child(1) { left: 5%; height: 40px; animation-duration: 2.8s; animation-delay: 0s; }
        .lonely-status-container .raindrop:nth-child(2) { left: 12%; height: 55px; animation-duration: 2.2s; animation-delay: 0.5s; }
        .lonely-status-container .raindrop:nth-child(3) { left: 20%; height: 35px; animation-duration: 3.2s; animation-delay: 1.1s; }
        .lonely-status-container .raindrop:nth-child(4) { left: 28%; height: 50px; animation-duration: 2.5s; animation-delay: 0.3s; }
        .lonely-status-container .raindrop:nth-child(5) { left: 35%; height: 45px; animation-duration: 2.9s; animation-delay: 0.8s; }
        .lonely-status-container .raindrop:nth-child(6) { left: 45%; height: 60px; animation-duration: 2.1s; animation-delay: 1.5s; }
        .lonely-status-container .raindrop:nth-child(7) { left: 55%; height: 38px; animation-duration: 3.0s; animation-delay: 0.2s; }
        .lonely-status-container .raindrop:nth-child(8) { left: 62%; height: 52px; animation-duration: 2.4s; animation-delay: 0.7s; }
        .lonely-status-container .raindrop:nth-child(9) { left: 72%; height: 42px; animation-duration: 2.7s; animation-delay: 1.3s; }
        .lonely-status-container .raindrop:nth-child(10) { left: 80%; height: 48px; animation-duration: 2.3s; animation-delay: 0.4s; }
        .lonely-status-container .raindrop:nth-child(11) { left: 88%; height: 36px; animation-duration: 3.1s; animation-delay: 0.9s; }
        .lonely-status-container .raindrop:nth-child(12) { left: 95%; height: 44px; animation-duration: 2.6s; animation-delay: 1.6s; }
        @keyframes rainFall {
            0% { transform: translateY(-100%); opacity: 0; }
            10% { opacity: 0.6; }
            90% { opacity: 0.4; }
            100% { transform: translateY(calc(100vh + 100%)); opacity: 0; }
        }

        .lonely-status-container .flow-layer {
            position: absolute;
            inset: 0;
            overflow: hidden;
            border-radius: 2px;
            z-index: 1;
            pointer-events: none;
        }
        .lonely-status-container .flow-line {
            position: absolute;
            height: 1px;
            background: linear-gradient(90deg,
                transparent 0%,
                rgba(0, 47, 167, 0.3) 20%,
                rgba(140, 180, 220, 0.5) 50%,
                rgba(0, 47, 167, 0.3) 80%,
                transparent 100%);
            animation: flowSweep linear infinite;
            opacity: 0;
        }
        .lonely-status-container .flow-line:nth-child(1) { top: 8%; width: 40%; animation-duration: 6s; animation-delay: 0s; }
        .lonely-status-container .flow-line:nth-child(2) { top: 22%; width: 55%; animation-duration: 5s; animation-delay: 1.2s; }
        .lonely-status-container .flow-line:nth-child(3) { top: 38%; width: 35%; animation-duration: 7s; animation-delay: 2.4s; }
        .lonely-status-container .flow-line:nth-child(4) { top: 52%; width: 50%; animation-duration: 5.5s; animation-delay: 0.8s; }
        .lonely-status-container .flow-line:nth-child(5) { top: 68%; width: 45%; animation-duration: 6.5s; animation-delay: 1.8s; }
        .lonely-status-container .flow-line:nth-child(6) { top: 82%; width: 38%; animation-duration: 5.2s; animation-delay: 3s; }
        @keyframes flowSweep {
            0% { transform: translateX(-100%); opacity: 0; }
            15% { opacity: 0.8; }
            85% { opacity: 0.6; }
            100% { transform: translateX(calc(100vw + 100%)); opacity: 0; }
        }

        .lonely-status-container .dust-layer {
            position: absolute;
            inset: 0;
            overflow: hidden;
            border-radius: 2px;
            z-index: 1;
            pointer-events: none;
        }
        .lonely-status-container .dust {
            position: absolute;
            border-radius: 50%;
            background: radial-gradient(circle, rgba(180, 200, 230, 0.9), transparent 70%);
            animation: dustFloat ease-in-out infinite;
        }
        .lonely-status-container .dust:nth-child(1) { width: 2px; height: 2px; top: 12%; left: 88%; animation-duration: 18s; animation-delay: 0s; }
        .lonely-status-container .dust:nth-child(2) { width: 1px; height: 1px; top: 28%; left: 8%; animation-duration: 22s; animation-delay: 3s; }
        .lonely-status-container .dust:nth-child(3) { width: 3px; height: 3px; top: 45%; left: 92%; animation-duration: 20s; animation-delay: 6s; }
        .lonely-status-container .dust:nth-child(4) { width: 1px; height: 1px; top: 62%; left: 12%; animation-duration: 24s; animation-delay: 2s; }
        .lonely-status-container .dust:nth-child(5) { width: 2px; height: 2px; top: 78%; left: 85%; animation-duration: 19s; animation-delay: 5s; }
        .lonely-status-container .dust:nth-child(6) { width: 1px; height: 1px; top: 35%; left: 45%; animation-duration: 21s; animation-delay: 8s; }
        .lonely-status-container .dust:nth-child(7) { width: 2px; height: 2px; top: 55%; left: 65%; animation-duration: 23s; animation-delay: 1s; }
        .lonely-status-container .dust:nth-child(8) { width: 1px; height: 1px; top: 88%; left: 35%; animation-duration: 17s; animation-delay: 4s; }
        @keyframes dustFloat {
            0%, 100% {
                transform: translate(0, 0) scale(1);
                opacity: 0.2;
            }
            25% {
                transform: translate(15px, -20px) scale(1.3);
                opacity: 0.6;
            }
            50% {
                transform: translate(-8px, -35px) scale(0.8);
                opacity: 0.4;
            }
            75% {
                transform: translate(20px, -15px) scale(1.1);
                opacity: 0.7;
            }
        }

        .lonely-status-container .glow-layer {
            position: absolute;
            inset: 0;
            overflow: hidden;
            border-radius: 2px;
            z-index: 1;
            pointer-events: none;
        }
        .lonely-status-container .glow-orb {
            position: absolute;
            border-radius: 50%;
            filter: blur(30px);
            animation: orbPulse ease-in-out infinite;
        }
        .lonely-status-container .glow-orb.orb-1 {
            width: 150px; height: 150px;
            top: 20%; left: 70%;
            background: radial-gradient(circle, rgba(0, 47, 167, 0.4), transparent 70%);
            animation-duration: 6s;
        }
        .lonely-status-container .glow-orb.orb-2 {
            width: 100px; height: 100px;
            top: 60%; left: 15%;
            background: radial-gradient(circle, rgba(26, 79, 217, 0.3), transparent 70%);
            animation-duration: 8s;
            animation-delay: 2s;
        }
        .lonely-status-container .glow-orb.orb-3 {
            width: 80px; height: 80px;
            top: 80%; left: 50%;
            background: radial-gradient(circle, rgba(184, 160, 104, 0.2), transparent 70%);
            animation-duration: 7s;
            animation-delay: 1s;
        }
        @keyframes orbPulse {
            0%, 100% { transform: scale(1); opacity: 0.3; }
            50% { transform: scale(1.2); opacity: 0.6; }
        }

        .lonely-status-container details {
            position: relative;
            z-index: 2;
        }
        .lonely-status-container details[open] .quote-summary {
            border-radius: 2px 2px 0 0;
        }

        .lonely-status-container .quote-summary {
            position: relative;
            padding: 28px 32px;
            cursor: pointer;
            list-style: none;
            background: linear-gradient(135deg, rgba(0, 17, 51, 0.7), rgba(0, 30, 80, 0.5));
            backdrop-filter: blur(20px);
            -webkit-backdrop-filter: blur(20px);
            border: 1px solid rgba(100, 140, 200, 0.15);
            border-radius: 2px;
            transition: all 0.5s cubic-bezier(0.4, 0, 0.2, 1);
            overflow: hidden;
        }
        .lonely-status-container .quote-summary::-webkit-details-marker { display: none; }
        .lonely-status-container .quote-summary::before {
            content: '';
            position: absolute;
            top: 0;
            left: -100%;
            width: 60%;
            height: 100%;
            background: linear-gradient(90deg, transparent, rgba(255,255,255,0.03), transparent);
            transition: left 0.8s;
        }
        .lonely-status-container .quote-summary:hover::before {
            left: 150%;
        }
        .lonely-status-container .quote-summary:hover {
            background: linear-gradient(135deg, rgba(0, 25, 70, 0.8), rgba(0, 40, 100, 0.6));
            border-color: rgba(120, 160, 220, 0.25);
            box-shadow:
                0 0 40px rgba(0, 47, 167, 0.2),
                inset 0 0 60px rgba(0, 47, 167, 0.05);
        }

        .lonely-status-container .quote-text {
            font-size: 1.1em;
            letter-spacing: 0.2em;
            line-height: 2;
            color: var(--text-soul);
            text-align: center;
            text-shadow: 0 0 30px var(--klein-glow), 0 0 60px rgba(0, 47, 167, 0.3);
            animation: quoteGlow 4s ease-in-out infinite alternate;
            position: relative;
        }
        .lonely-status-container .quote-text::before,
        .lonely-status-container .quote-text::after {
            content: '·';
            position: absolute;
            top: 50%;
            transform: translateY(-50%);
            font-size: 0.5em;
            color: var(--gold-whisper);
            opacity: 0.4;
        }
        .lonely-status-container .quote-text::before { left: -20px; }
        .lonely-status-container .quote-text::after { right: -20px; }
        @keyframes quoteGlow {
            0% {
                text-shadow: 0 0 20px var(--klein-glow), 0 0 40px rgba(0, 47, 167, 0.2);
                opacity: 0.9;
            }
            100% {
                text-shadow: 0 0 35px var(--klein-glow), 0 0 70px rgba(0, 47, 167, 0.4), 0 0 100px rgba(0, 47, 167, 0.2);
                opacity: 1;
            }
        }

        .lonely-status-container .memory-preview {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 10px;
            margin-top: 14px;
            font-size: 0.8em;
            color: var(--text-ash);
            opacity: 0.7;
            transition: all 0.4s;
        }
        .lonely-status-container .quote-summary:hover .memory-preview {
            opacity: 1;
            color: var(--text-ghost);
        }
        .lonely-status-container .memory-tag {
            padding: 3px 12px;
            background: rgba(184, 160, 104, 0.1);
            border: 1px solid rgba(184, 160, 104, 0.2);
            border-radius: 12px;
            font-size: 0.85em;
            color: var(--gold-whisper);
            letter-spacing: 0.1em;
        }

        .lonely-status-container .expand-hint {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 8px;
            margin-top: 18px;
            font-size: 0.75em;
            color: var(--text-ash);
            letter-spacing: 0.15em;
        }
        .lonely-status-container .expand-hint .arrow {
            display: inline-block;
            transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
            animation: arrowPulse 2s ease-in-out infinite;
        }
        @keyframes arrowPulse {
            0%, 100% { transform: translateY(0); opacity: 0.5; }
            50% { transform: translateY(3px); opacity: 0.8; }
        }
        .lonely-status-container details[open] .expand-hint .arrow {
            transform: rotate(180deg);
            animation: none;
        }

        .lonely-status-container .status-content {
            background: linear-gradient(180deg, rgba(0, 20, 50, 0.6), rgba(5, 10, 20, 0.8));
            backdrop-filter: blur(15px);
            -webkit-backdrop-filter: blur(15px);
            border: 1px solid rgba(100, 140, 200, 0.1);
            border-top: none;
            border-radius: 0 0 2px 2px;
            animation: contentFadeIn 0.6s cubic-bezier(0.4, 0, 0.2, 1);
            transform-origin: top;
            overflow: hidden;
        }
        @keyframes contentFadeIn {
            0% {
                opacity: 0;
                transform: scaleY(0.9) translateY(-15px);
            }
            100% {
                opacity: 1;
                transform: scaleY(1) translateY(0);
            }
        }

        .lonely-status-container .time-section {
            padding: 24px 28px 20px;
            display: grid;
            grid-template-columns: 1fr auto 1fr;
            align-items: center;
            gap: 20px;
            border-bottom: 1px solid rgba(100, 140, 200, 0.1);
            position: relative;
        }
        .lonely-status-container .time-section::after {
            content: '';
            position: absolute;
            bottom: 0;
            left: 20%;
            right: 20%;
            height: 1px;
            background: linear-gradient(90deg, transparent, var(--gold-whisper), transparent);
            opacity: 0.3;
        }
        .lonely-status-container .time-left {
            text-align: left;
        }
        .lonely-status-container .time-right {
            text-align: right;
        }
        .lonely-status-container .date-text {
            font-size: 0.85em;
            color: var(--text-ghost);
            letter-spacing: 0.12em;
        }
        .lonely-status-container .time-text {
            font-size: 2em;
            color: var(--text-soul);
            letter-spacing: 0.08em;
            text-shadow: 0 0 25px var(--klein-glow);
            margin-top: 4px;
            animation: timeGlow 3s ease-in-out infinite alternate;
        }
        @keyframes timeGlow {
            0% { text-shadow: 0 0 15px var(--klein-glow); }
            100% { text-shadow: 0 0 30px var(--klein-glow), 0 0 50px rgba(0, 47, 167, 0.4); }
        }
        .lonely-status-container .weather-tag {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 8px 16px;
            background: rgba(255, 255, 255, 0.04);
            border: 1px solid rgba(100, 140, 200, 0.15);
            border-radius: 20px;
            font-size: 0.85em;
            color: var(--text-ghost);
            transition: all 0.4s;
        }
        .lonely-status-container .weather-tag:hover {
            background: rgba(255, 255, 255, 0.08);
            border-color: rgba(140, 180, 220, 0.25);
            transform: translateY(-2px);
            box-shadow: 0 4px 15px rgba(0, 47, 167, 0.2);
        }
        .lonely-status-container .location-text {
            font-size: 0.8em;
            color: var(--text-ash);
            margin-top: 8px;
            letter-spacing: 0.05em;
        }
        .lonely-status-container .time-center {
            text-align: center;
        }
        .lonely-status-container .center-deco {
            font-size: 0.6em;
            color: var(--gold-whisper);
            letter-spacing: 0.4em;
            opacity: 0.6;
            text-transform: uppercase;
        }
        .lonely-status-container .center-title {
            font-size: 1em;
            color: var(--text-soul);
            letter-spacing: 0.3em;
            margin: 6px 0;
            opacity: 0.8;
        }

        .lonely-status-container .chars-section {
            display: grid;
            grid-template-columns: 1fr 1fr;
        }
        .lonely-status-container .char-panel {
            padding: 22px 24px;
            position: relative;
            transition: all 0.4s;
        }
        .lonely-status-container .char-panel:hover {
            background: rgba(255, 255, 255, 0.02);
        }
        .lonely-status-container .char-panel:first-child {
            border-right: 1px solid rgba(100, 140, 200, 0.1);
        }
        .lonely-status-container .char-panel:first-child::after {
            content: '';
            position: absolute;
            right: 0;
            top: 20%;
            height: 60%;
            width: 1px;
            background: linear-gradient(180deg, transparent, var(--gold-whisper), transparent);
            opacity: 0.2;
        }
        .lonely-status-container .char-name {
            font-size: 0.95em;
            color: var(--gold-whisper);
            letter-spacing: 0.25em;
            margin-bottom: 14px;
            padding-bottom: 10px;
            border-bottom: 1px dashed rgba(100, 140, 200, 0.15);
            text-shadow: 0 0 15px rgba(184, 160, 104, 0.2);
        }
        .lonely-status-container .char-tags {
            display: flex;
            flex-wrap: wrap;
            gap: 8px;
            margin-bottom: 16px;
        }
        .lonely-status-container .tag {
            padding: 5px 14px;
            background: rgba(255, 255, 255, 0.04);
            border: 1px solid rgba(100, 140, 200, 0.12);
            border-radius: 16px;
            font-size: 0.78em;
            color: var(--text-ghost);
            transition: all 0.3s;
        }
        .lonely-status-container .tag:hover {
            background: rgba(255, 255, 255, 0.08);
            border-color: rgba(140, 180, 220, 0.25);
            transform: translateY(-1px);
        }
        .lonely-status-container .tag.mood {
            color: var(--text-soul);
            border-color: rgba(154, 90, 104, 0.3);
            background: rgba(154, 90, 104, 0.08);
        }

        .lonely-status-container .stat-bars {
            display: flex;
            flex-direction: column;
            gap: 12px;
        }
        .lonely-status-container .stat-row {
            display: flex;
            align-items: center;
            gap: 12px;
        }
        .lonely-status-container .stat-name {
            font-size: 0.72em;
            color: var(--text-ash);
            min-width: 40px;
            letter-spacing: 0.1em;
        }
        .lonely-status-container .stat-track {
            flex: 1;
            height: 4px;
            background: rgba(255, 255, 255, 0.06);
            border-radius: 2px;
            overflow: hidden;
            position: relative;
        }
        .lonely-status-container .stat-fill {
            height: 100%;
            border-radius: 2px;
            transition: width 1s cubic-bezier(0.4, 0, 0.2, 1);
            position: relative;
            overflow: hidden;
        }
        .lonely-status-container .stat-fill::after {
            content: '';
            position: absolute;
            top: 0;
            left: -100%;
            width: 100%;
            height: 100%;
            background: linear-gradient(90deg, transparent, rgba(255,255,255,0.4), transparent);
            animation: statShimmer 2.5s ease-in-out infinite;
        }
        @keyframes statShimmer {
            0% { left: -100%; }
            100% { left: 200%; }
        }
        .lonely-status-container .stat-fill.hp {
            background: linear-gradient(90deg, #2a6b5a, #4a9a7a);
            box-shadow: 0 0 10px rgba(74, 154, 122, 0.3);
        }
        .lonely-status-container .stat-fill.mental {
            background: linear-gradient(90deg, #3a5a8a, #5a7aaa);
            box-shadow: 0 0 10px rgba(90, 122, 170, 0.3);
        }
        .lonely-status-container .stat-fill.fatigue {
            background: linear-gradient(90deg, #8a6a2a, #ba9a4a);
            box-shadow: 0 0 10px rgba(186, 154, 74, 0.3);
        }
        .lonely-status-container .stat-fill.hatred {
            background: linear-gradient(90deg, #8a3a4a, #ba5a6a);
            box-shadow: 0 0 10px rgba(186, 90, 106, 0.3);
        }
        .lonely-status-container .stat-num {
            font-size: 0.72em;
            color: var(--text-ghost);
            min-width: 24px;
            text-align: right;
        }

        .lonely-status-container .detail-section {
            padding: 18px 28px;
            border-top: 1px solid rgba(100, 140, 200, 0.1);
        }
        .lonely-status-container .detail-item {
            display: flex;
            align-items: flex-start;
            gap: 14px;
            padding: 12px 0;
            border-bottom: 1px dashed rgba(100, 140, 200, 0.08);
            transition: all 0.3s;
        }
        .lonely-status-container .detail-item:last-child {
            border-bottom: none;
        }
        .lonely-status-container .detail-item:hover {
            background: rgba(255, 255, 255, 0.015);
            padding-left: 8px;
        }
        .lonely-status-container .detail-icon {
            font-size: 0.95em;
            opacity: 0.7;
            margin-top: 2px;
        }
        .lonely-status-container .detail-box {
